select mn.Pay_Id, mn.Pay_Type, mn.Pay_Type_Detailed, mn.Pay_Apply, mn.Pay_Approval, mn.Pay_Apply_Owner, mn.Pay_Application_Date from Con_Pay mn where mn.Con_Id=#{params.conId} and (mn.Contract_Pay_Type = '1' or mn.Contract_Pay_Type is null)
and mn.Te_Id = #{params.teId}
and mn.Pay_State=7 and mn.Pay_Category='01'

select coalesce(sum(mn.Pay_Apply), 0) as payApplySum, coalesce(sum(mn.Pay_Approval), 0) as payApprovalSum, coalesce(sum(mn.Pay_Apply_Owner), 0) as payApplyOwnerSum from Con_Pay mn where mn.Con_Id=#{params.conId} and (mn.Contract_Pay_Type = '1' or mn.Contract_Pay_Type is null)
and mn.Te_Id = #{params.teId}
and mn.Pay_State=7 and mn.Pay_Category='01'

select mn.*
from Con_Fund_No mn
where mn.Pay_Id = #{payId}

select
mn.*
from Con_Pay mn
where mn.Pay_State=7
and (mn.Contract_Pay_Type = '1' or mn.Contract_Pay_Type is null)

    and mn.Te_Id = #{params.teId}


    and mn.Con_Id = #{params.conId}


    and mn.Pay_Type_Detailed = #{params.payTypeDetailed}


    and mn.Pay_Type = #{params.payType}

order by mn.Pay_State_Time desc
limit 1

