select
con.Con_Name as conName, con.Con_Code as conCode, con.Con_Money_Total as conMoneyTotal, con.Con_Type as conType, con.con_Term as conTerm, c1.C_Name as payPayeeName, c2.C_Name as payDraweeName, c3.C_Name as payApplicantName, c4.C_Name as conPartyBName, c1.C_Abbreviation as payPayeeAbbName, c2.C_Abbreviation as payDraweeAbbName, c3.C_Abbreviation as payApplicantAbbName, c4.C_Abbreviation as conPartyBAbbName, dep.D_Name as dName, dep1.D_Name as payApplicationDepartmentName, f.file_relation_id as fileRelationId,
(select SUM(cpfa.cpaf_Application) from Con_Pay_Apply_Flow cpfa where cpfa.pay_id=mn.pay_id and cpfa.state=7) as cpafApplicationSum,
mn.*,CASE WHEN mn.Pay_Application_Date IS NOT NULL THEN YEAR(mn.Pay_Application_Date) WHEN mn.Pay_Create_Time IS NOT NULL THEN YEAR(mn.Pay_Create_Time) END as payYear, CASE WHEN mn.Pay_Application_Date IS NOT NULL THEN MONTH(mn.Pay_Application_Date) WHEN mn.Pay_Create_Time IS NOT NULL THEN MONTH(mn.Pay_Create_Time) END as payMonth from Con_Pay mn left join Con_Contract con on con.Con_Id=mn.Con_Id
left join SYS_Company c1 on c1.C_Id=mn.Pay_Payee left join SYS_Company c2 on c2.C_Id=mn.Pay_Drawee left join SYS_Company c3 on c3.C_Id=mn.Pay_Applicant_Id left join SYS_Company c4 on c4.C_Id=con.Con_Party_B_Id left join SYS_Department dep on dep.D_Id=mn.D_Id left join SYS_Department dep1 on dep1.D_Id=mn.Pay_Application_Department_Id left join Sys_File f on f.FileID=mn.Pay_Id ${params.authSql}
and mn.Pay_Create_Uid = #{params.uId}
AND mn.P_ID IN
#{item}
AND mn.P_ID NOT IN
#{item}
and (CASE WHEN mn.Pay_Application_Date IS NOT NULL THEN YEAR(mn.Pay_Application_Date) WHEN mn.Pay_Create_Time IS NOT NULL THEN YEAR(mn.Pay_Create_Time) END) = #{params.payYear}
and (CASE WHEN mn.Pay_Application_Date IS NOT NULL THEN MONTH(mn.Pay_Application_Date) WHEN mn.Pay_Create_Time IS NOT NULL THEN MONTH(mn.Pay_Create_Time) END) = #{params.payMonth}
and pro.P_Name like concat('%',#{params.projectName},'%')
and con.con_name like concat('%',#{params.contractName},'%')
and mn.Pay_State!=3 and mn.Pay_State!=0
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Pay_Create_Time desc

