select * from ( select ROW_NUMBER() over(partition by mn.Con_Id order by mn.Pay_Create_Time desc) as rn,
con.Con_Name as conName, con.Con_Code as conCode, con.Con_Money_Total as conMoneyTotal, con.Con_Type as conType, con.Con_Party_A_Id as conPartyAId, con.con_department as conDepartment, cdep.D_Name as conDepName, c1.C_Name as payPayeeName, c2.C_Name as payDraweeName, c3.C_Name as payApplicantName, c4.C_Name as conPartyBName, c5.C_Name as conPartyAName, c1.C_Abbreviation as payPayeeAbbName, c2.C_Abbreviation as payDraweeAbbName, c3.C_Abbreviation as payApplicantAbbName, c4.C_Abbreviation as conPartyBAbbName, dep.D_Name as dName, dep1.D_Name as payApplicationDepartmentName, f.file_relation_id as fileRelationId, mn.* from Con_Pay mn left join Con_Contract con on con.Con_Id=mn.Con_Id
left join SYS_Company c1 on c1.C_Id=mn.Pay_Payee left join SYS_Company c2 on c2.C_Id=mn.Pay_Drawee left join SYS_Company c3 on c3.C_Id=mn.Pay_Applicant_Id left join SYS_Company c4 on c4.C_Id=con.Con_Party_B_Id left join SYS_Company c5 on c5.C_Id=con.Con_Party_A_Id left join SYS_Department cdep on cdep.D_Id=con.con_department left join SYS_Department dep on dep.D_Id=mn.D_Id left join SYS_Department dep1 on dep1.D_Id=mn.Pay_Application_Department_Id left join Sys_File f on f.FileID=mn.Pay_Id ${params.authSql}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Pay_Create_Time desc
) t1 where t1.rn = 1

select sum(t1.Pay_Work_Amount_Total) as payWorkAmountTotalSum, sum(t1.Pay_Apply) as payApplySum, sum(t1.Pay_Unfinished_Work) as payUnfinishedWorkSum, sum(t1.Pay_Liquidated_Damages) as payLiquidatedDamagesSum, sum(t1.Pay_Deduct_Qt) as payDeductQtSum, sum(t1.Pay_Approva_Change_Total) as payApprovaChangeTotalSum, sum(t1.Pay_Total_Last) as payTotalLastSum, sum(t1.Pay_Total) as payTotalSum, sum(t1.Pay_Done) as payDoneSum from ( select ROW_NUMBER() over(partition by mn.Con_Id order by mn.Pay_Create_Time desc) as rn, mn.* from Con_Pay mn left join Con_Contract con on con.Con_Id=mn.Con_Id
left join SYS_Company c1 on c1.C_Id=mn.Pay_Payee left join SYS_Company c2 on c2.C_Id=mn.Pay_Drawee left join SYS_Company c3 on c3.C_Id=mn.Pay_Applicant_Id left join SYS_Company c4 on c4.C_Id=con.Con_Party_B_Id left join SYS_Company c5 on c5.C_Id=con.Con_Party_A_Id left join SYS_Department cdep on cdep.D_Id=con.con_department left join SYS_Department dep on dep.D_Id=mn.D_Id left join SYS_Department dep1 on dep1.D_Id=mn.Pay_Application_Department_Id left join Sys_File f on f.FileID=mn.Pay_Id ${params.authSql}
) t1 where t1.rn = 1

select sum(Pay_Done) as payDoneSum
from Con_Pay
where Con_Id = #{conId}
and (Contract_Pay_Type = '1' or Contract_Pay_Type is null)
  and Pay_State = 7
  and Pay_Type = #{payType}

select top 1 mn.* from Con_Pay mn where mn.P_Id=#{projectId} and mn.Pay_Category=#{payCategory} and mn.Pay_State = 7 and (Contract_Pay_Type = '1' or Contract_Pay_Type is null)
and mn.Con_Id = #{contractId}
order by Pay_Create_Time desc

select mn.* from Con_Pay mn where mn.P_Id=#{projectId} and (mn.Pay_Type is null or mn.Pay_Type == '') and mn.Pay_State = 7 and (Contract_Pay_Type = '1' or Contract_Pay_Type is null)
and mn.Con_Id = #{contractId}
order by Pay_Create_Time desc

